def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 > v2:
        result = "2019"
    elif v2 > v1:
        result = "2018"
    else:
        result = "Equal"

    return {
        "value": result,
        "trace": {
            "2019": v1,
            "2018": v2,
            "comparison": "2019" if v1 > v2 else "2018" if v2 > v1 else "Equal",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
